18:     public static Map<String, String> capture(Class<?> entrypoint, String configuredKernel,
19:                                               String effectiveKernel, Map<String, String> behavior) {
20:         try {
21:             var identity = new TreeMap<String, String>();
22:             var classpath = System.getProperty("java.class.path", "");
23:             if (classpath.isBlank()) throw new IOException("runtime classpath is missing");
24:             var entries = classpath.split(java.util.regex.Pattern.quote(java.io.File.pathSeparator), -1);
25:             Path executable = entries.length == 1 ? Path.of(entries[0]).toAbsolutePath().normalize() : null;
26:             if (executable != null && Files.isRegularFile(executable) && isBootEntry(executable, entrypoint)) {
27:                 var bundle = new TreeMap<String, Path>();
28:                 var role = role(executable);
29:                 bundle.put(role, executable);
30:                 var other = sibling(executable, role);
31:                 if (Files.isRegularFile(other)) bundle.put(role.equals("cli") ? "server" : "cli", other);
32:                 identity.putAll(packaged(bundle));
33:             } else {
34:                 // Preserve classpath order: reordering shadowed classes changes executable behavior.
35:                 for (int index = 0; index < entries.length; index++) {
36:                     if (entries[index].isBlank()) throw new IOException("empty runtime classpath entry");
37:                     identity.put("classpath." + String.format("%04d", index), content(Path.of(entries[index])));
38:                 }
39:                 var source = Path.of(entrypoint.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath();
40:                 boolean found = false;
41:                 for (var entry : entries) if (Path.of(entry).toRealPath().equals(source)) found = true;
42:                 if (!found) throw new IOException("entrypoint code source is outside the captured classpath");
43:             }
44:             identity.put("identity_schema", "dual-runtime-content.v1");
45:             identity.put("kernel.configured", configuredKernel == null ? "" : configuredKernel);
46:             identity.put("kernel.effective", java.util.Objects.requireNonNull(effectiveKernel));
47:             identity.put("java.runtime", System.getProperty("java.runtime.version"));
48:             // Only explicit non-secret behavior settings may be supplied; never capture the whole environment.
49:             behavior.forEach((key, value) -> identity.put("behavior." + key, value));
50:             return Map.copyOf(identity);
51:         } catch (Exception failure) {
52:             throw new IllegalStateException("cannot establish frozen runtime content identity", failure);
53:         }
54:     }
